def solve(events):
    ledger={}
    for event in events:
        key,value=event['key'],event['value']
        if not isinstance(key,str) or not key or type(value) is not int: raise ValueError('event')
        if key in ledger and ledger[key]!=value: raise ValueError('conflicting retry')
        ledger[key]=value
    return sum(ledger.values())

